widget.prelude:
from math import erf, exp, log, sqrt, pi

def norm_cdf(z):
    return 0.5 * (1 + erf(z / sqrt(2)))

def norm_pdf(z):
    return exp(-z * z / 2) / sqrt(2 * pi)

def bs_call(S, K, r, sigma, T):
    d1 = (log(S / K) + (r + sigma ** 2 / 2) * T) / (sigma * sqrt(T))
    d2 = d1 - sigma * sqrt(T)
    return S * norm_cdf(d1) - K * exp(-r * T) * norm_cdf(d2)
